using Health_Care_System.BLL.Interfaces; using Health_Care_System.BLL.Implementations; using Health_Care_System.BLL.Services; using Health_Care_System.Data; using Health_Care_System.Data.Interceptors; using Health_Care_System.Entities; using Health_Care_System.PL.Helper; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using System.Reflection;
namespace Health_Care_System.PL.Extensions; public static class ApplicationServiceExtension { public static IServiceCollection AddServices(this IServiceCollection services,IConfiguration configuration){services.AddControllersWithViews();services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(configuration.GetConnectionString("DefaultSqlConnection")).AddInterceptors(new SoftDeleteInterceptor(),new CreatedAtInterceptor(),new ModifiedAtInterceptor()));services.AddDbContext<AuthenticationDbContext>(o=>o.UseSqlServer(configuration.GetConnectionString("AuthenticationConnection")));services.AddIdentity<ApplicationUser,IdentityRole>(o=>{o.Password.RequireDigit=true;o.Password.RequiredLength=6;o.Password.RequireNonAlphanumeric=false;}).AddEntityFrameworkStores<AuthenticationDbContext>().AddDefaultTokenProviders();services.ConfigureApplicationCookie(o=>{o.LoginPath="/Account/Login";o.AccessDeniedPath="/Account/Login";});services.AddScoped<IUnitOfWork,UnitOfWork>();services.AddScoped<IPatientService,PatientService>();services.AddScoped<IDoctorService,DoctorService>();services.AddScoped<IAppointmentService,AppointmentService>();services.AddAutoMapper(cfg=>cfg.AddMaps(Assembly.GetExecutingAssembly()));return services;} }
